    """
    Written by a member: ThirdPartyText when another member wrote it. A plain string when the caller wrote it, or with text=plain.
    """
    lot_path: NotRequired[str | None]
    seller: NotRequired[Seller]
    payment: NotRequired[Payment | None]
    fulfillment: NotRequired[Fulfillment | None]
    dispute: NotRequired[Dispute1 | None]
    rating: NotRequired[Rating1 | None]
    fulfillment_kind: NotRequired[
        Literal['ship', 'pickup', 'local_delivery', 'freight']
    ]
    """
    ship, pickup, local_delivery or freight.
    """
    pickup: NotRequired[Pickup2 | None]
    pickup_card_url: NotRequired[str | None]
    po_number: NotRequired[str | None]
    po_number_editable: NotRequired[bool]
    """
    True until the seller ships; then the number is fixed.
    """
    tax_exempt: NotRequired[bool]
    """
    true when a tax exemption certificate on file covered the ship-to state (the pickup state for a pickup) when the order was placed. CommerceBook calculates no sales tax today; tax_cents stays 0 either way.
    """
    tax_exemption: NotRequired[OrderTaxExemption | None]


